 const offNative=services.editorSession?.subscribe(next=>{state.native=next;state.proposal=next.proposal;const signature=JSON.stringify({sessionId:next.sessionId,connecting:next.connecting,nativeConnection:next.nativeConnection,error:next.error,toolError:next.toolError,running:next.running,execution:next.execution,proposal:next.proposal?{id:next.proposal.id,configurationHash:next.proposal.configurationHash,stale:next.proposal.stale}:null});if(signature!==nativeSignature){nativeSignature=signature;if(!nativeRenderQueued){nativeRenderQueued=true;queueMicrotask(()=>{nativeRenderQueued=false;if(!dead)render();});}}});

 root.classList.add('ares-app','ares-system','ares-galaxy');root.dataset.aresUi='galaxy';root.dataset.aresMotion=state.motionEnabled?'on':'off';
 const uiMotion=createInterfaceMotion(root);
